import json
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
out=Path(__file__).parent;checks=[]
def note(n,d):checks.append({'check':n,'observed':d});(out/'phone-safety-review.json').write_text(json.dumps(checks,indent=2,ensure_ascii=False),encoding='utf-8');print(n,str(d)[:250],flush=True)
def opt(page,id):page.locator('.lab summary').click();page.locator(id).check();page.locator('.lab summary').click()
def st(page):return page.evaluate('JSON.parse(localStorage.getItem("dubbed-studio-lowfi-v1"))')
def click_min(page,sel):
 r=page.locator(sel).bounding_box();delta=max(0,r['y']+r['height']-page.viewport_size['height']+8)
 if delta:page.mouse.wheel(0,delta);page.wait_for_timeout(200)
 r=page.locator(sel).bounding_box();page.mouse.click(r['x']+r['width']/2,r['y']+r['height']/2)
def cap(page,name):
 click_min(page,'#record');expect(page.locator('#capture-badge')).to_be_visible();page.wait_for_timeout(150);d=page.locator('#scene,#dialogue,#capture-badge').evaluate_all('(es)=>es.map(e=>({id:e.id,rect:e.getBoundingClientRect().toJSON()}))');assert all(e['rect']['top']>=0 and e['rect']['bottom']<=667 for e in d);note(name+' visible capture context',d);page.screenshot(path=str(out/(name+'.png')));page.wait_for_function('!document.querySelector("#take").disabled',timeout=10000);page.wait_for_timeout(180);assert page.locator('.wave').get_attribute('data-overlay-progress')=='1'
with sync_playwright() as p:
 b=p.chromium.launch(channel='chrome',headless=True);page=b.new_page(viewport={'width':390,'height':667},device_scale_factor=1,reduced_motion='reduce');errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://127.0.0.1:5179');page.wait_for_function('document.querySelector("#scene").readyState>=3');page.locator('.lab summary').click();page.locator('#locale').select_option('ru');page.locator('#long-line').check();page.locator('.lab summary').click();cap(page,'studio-review-phone-first-capture');first=st(page)['candidates'][0]['id'];click_min(page,'#next');expect(page.locator('#position')).to_contain_text('2');assert page.locator('#dots span[aria-current=true]').get_attribute('aria-label') is not None;cap(page,'studio-review-phone-next-capture');page.locator('#previous').click();expect(page.locator('#guard')).to_be_visible();page.locator('#guard button').nth(2).click();expect(page.locator('#position')).to_contain_text('1');assert st(page)['accepted'][0]['id']==first;old=st(page)['accepted'][0]['id'];cap(page,'studio-review-phone-replacement');c=st(page)['candidates'][0]['id'];opt(page,'#fail-mic');page.locator('#record').click();expect(page.locator('#feedback')).to_be_visible();assert st(page)['candidates'][0]['id']==c and st(page)['accepted'][0]['id']==old;assert page.locator('.wave').get_attribute('data-overlay-progress')=='1';note('Blocked recapture protects candidate, prior accepted ID and completed overlay',True);cap(page,'studio-review-phone-recapture');c=st(page)['candidates'][0]['id'];opt(page,'#fail-save');page.locator('#next').click();expect(page.locator('#feedback')).to_be_visible();assert st(page)['candidates'][0]['id']==c and st(page)['accepted'][0]['id']==old;page.locator('#take').click();page.wait_for_function('!document.querySelector("#take-audio").paused && document.querySelector("#take-audio").currentTime>.2');page.locator('#pause').click();page.reload();expect(page.locator('#take')).to_be_enabled();assert st(page)['candidates'][0]['id']==c and st(page)['accepted'][0]['id']==old;assert page.locator('.wave').get_attribute('data-has-take')=='true';page.screenshot(path=str(out/'studio-review-phone-protected-reload.png'),full_page=True);page.locator('#next').click();expect(page.locator('#position')).to_contain_text('2');assert st(page)['accepted'][0]['id']==c;note('Failed replacement/reload keep exact media; Retry accepts candidate',{'oldAccepted':old,'replacement':c});note('Page errors',errors);assert not errors;b.close()
